#!/usr/bin/env bash
# step88 — Phase 3b-ii: Mode-B credential delivery. Login-gated, ownership-
# checked credentials page; the 'delivered' WhatsApp message sends its secure
# link instead of raw credentials. Adds site_base_url, the credentials route
# + view, and patches notifyCustomerWa. Requires step87. Idempotent; rollback.
set -euo pipefail
APP=/opt/gsz
TS=$(date +%Y%m%d-%H%M%S)
BAK=$APP/.bak-step88-$TS
mkdir -p "$BAK/routes" "$BAK/views/account"
cp "$APP/routes/checkout.js" "$BAK/routes/checkout.js"
cp "$APP/routes/whatsapp.js" "$BAK/routes/whatsapp.js"
restore(){ echo "!! rollback"; cp "$BAK/routes/checkout.js" "$APP/routes/checkout.js"; cp "$BAK/routes/whatsapp.js" "$APP/routes/whatsapp.js"; rm -f "$APP/views/account/credentials.ejs"; pm2 restart gsz --update-env >/dev/null 2>&1 || true; }
trap 'restore' ERR
cd "$APP"

echo "==> seed site_base_url"
node <<'NODE'
require('dotenv').config();
const { Pool } = require('pg');
const p = new Pool({ host:process.env.DB_HOST, port:process.env.DB_PORT, database:process.env.DB_NAME, user:process.env.DB_USER, password:process.env.DB_PASS });
(async()=>{
  await p.query("INSERT INTO wa_settings(key,value) VALUES('site_base_url','http://143.198.209.68:3900') ON CONFLICT(key) DO NOTHING");
  const v=(await p.query("SELECT value FROM wa_settings WHERE key='site_base_url'")).rows[0].value;
  console.log('   site_base_url = '+v);
  await p.end();
})().catch(e=>{ console.error('FAIL: '+e.message); process.exit(1); });
NODE

echo "==> overwrite whatsapp.js (adds /account/order/:no/credentials) + write view"
base64 -d > "$APP/routes/whatsapp.js" <<'B64'

B64
base64 -d > "$APP/views/account/credentials.ejs" <<'B64'

B64

echo "==> patch checkout.js (credential Mode-B link in notifyCustomerWa)"
node <<'NODE'
const fs=require('fs'); const f='/opt/gsz/routes/checkout.js'; let s=fs.readFileSync(f,'utf8');
if(s.indexOf('secLink')>=0){ console.log('   checkout already has credential wiring'); }
else {
  const o1="    const map = { 'new':'whatsapp.order_received', 'paid':'whatsapp.payment_confirmed', 'delivered':'whatsapp.order_completed' };\n    const tplKey = map[event]; if (!tplKey) return;";
  if(s.indexOf(o1)<0){ console.error('!! notifyCustomerWa anchor not found — deploy step87 first'); process.exit(2); }
  const n1="    let tplKey; let secLink='';\n"
   +"    if (event==='new') tplKey='whatsapp.order_received';\n"
   +"    else if (event==='paid') tplKey='whatsapp.payment_confirmed';\n"
   +"    else if (event==='delivered') { if (o.delivered_credentials) { tplKey='whatsapp.credentials'; const base=(((await pool.query(\"SELECT value FROM wa_settings WHERE key='site_base_url'\")).rows[0])||{}).value||''; secLink = base ? (base.replace(/\\/+$/,'')+'/account/order/'+encodeURIComponent(o.order_no||'')+'/credentials') : ''; } else tplKey='whatsapp.order_completed'; }\n"
   +"    if (!tplKey) return;";
  s=s.replace(o1,n1);
  const o2="customer_reference:cust.ref_code||'' }, idempotency_key:";
  if(s.indexOf(o2)<0){ console.error('!! enqueue vars anchor not found'); process.exit(3); }
  s=s.replace(o2,"customer_reference:cust.ref_code||'', secure_link:secLink }, idempotency_key:");
  fs.writeFileSync(f,s); console.log('   checkout.js patched (credential Mode-B link)');
}
NODE

echo "==> node --check + ejs compile"
node --check "$APP/routes/checkout.js"; node --check "$APP/routes/whatsapp.js"
node -e "const ejs=require('ejs'),fs=require('fs');ejs.compile(fs.readFileSync('$APP/views/account/credentials.ejs','utf8'),{filename:'x'});console.log('   credentials.ejs compiles');"

echo "==> restart + health"; pm2 restart gsz --update-env >/dev/null; sleep 3
grep -q '</html>' <<<"$(curl -s -m 15 http://127.0.0.1:3900/ || true)" || { echo "!! home broken"; false; }
C1=$(curl -s -o /dev/null -w '%{http_code}' -m 10 "http://127.0.0.1:3900/account/order/GSZ-0000/credentials" || true)
[ "$C1" = "302" ] || { echo "!! credentials page should redirect to login when signed out (got $C1)"; false; }
trap - ERR
echo "==> step88 OK — Mode-B credential delivery live. Backup: $BAK"
echo "   Delivered orders message a secure, login-gated link instead of raw credentials."
